SELECT
  CAST(
    (
      (
        MAX(CASE WHEN T2.positionOrder = 1 THEN T2.milliseconds ELSE 0 END) - MAX(T2.milliseconds)
      ) * 100
    ) AS REAL
  ) / MAX(T2.milliseconds)
FROM races AS T1
INNER JOIN results AS T2
  ON T1.raceId = T2.raceId
WHERE
  T1.year = 2008 AND T1.name = 'Australian Grand Prix';

